mapper.select:
select DATE(order_time) as day,sum(amount) as total from orders
where status=5
and order_time >= #{begin}
and order_time < #{end}
group by DATE(order_time)
order by day;

select count(*) from user


        and create_time >= #{beginTime}


        and create_time < #{endTime}

select count(*) from orders


        and order_time >= #{beginTime}


        and order_time < #{endTime}


        and status =#{status}

select od.name, sum(od.number) as number
from orders as o inner join order_detail as od
ON o.id = od.order_id


       and o.status = #{status}


      and  o.order_time >= #{beginTime}


      and o.order_time < #{endTime}


GROUP BY od.name
ORDER BY sum(od.number) desc, od.name
limit #{N}
